    private function movementEvents(string $key,array $filters): Collection {
        $hotel=str_contains($key,'check');
        $table=$hotel?'booking_group_package_hotels':'booking_group_package_flights';
        $events=collect();
        if($hotel){
            if(!Schema::hasTable($table)) return $events;
            $cols=Schema::getColumnListing($table);
            $date=str_contains($key,'checkin')?collect(['check_in','checkin','check_in_date'])->first(fn($c)=>in_array($c,$cols,true)):collect(['check_out','checkout','check_out_date'])->first(fn($c)=>in_array($c,$cols,true));
            $city=collect(['city','city_name','destination'])->first(fn($c)=>in_array($c,$cols,true));
            if(!$date||!$city)return$events;
            $q=DB::table($table.' as event')->select('event.*')->whereNotNull('event.'.$date)->where('event.'.$city,'like','%'.(str_contains($key,'makkah')?'makkah':'madinah').'%');
            if(($filters['from']??'')!=='')$q->whereDate('event.'.$date,'>=',$filters['from']);if(($filters['to']??'')!=='')$q->whereDate('event.'.$date,'<=',$filters['to']);if(Schema::hasTable('bookings')&&Schema::hasColumn($table,'booking_id'))$this->applyBookingRelationFilters($q,$filters,$table,'event');
            return $q->get();
