            $cols=Schema::getColumnListing('booking_itinerary_segments');$pick=fn(array $names)=>collect($names)->first(fn($c)=>in_array($c,$cols,true));
            $arrival=$pick(['arrival_at','arrival_datetime','arrival_date']);$departure=$pick(['departure_at','departure_datetime','departure_date']);$from=$pick(['from','from_code','origin','origin_code']);$to=$pick(['to','to_code','destination','destination_code']);$flight=$pick(['flight_number','flight_no','flight']);$type=$pick(['segment_type','type']);
            $date=$key==='arrival'?$arrival:$departure;
            if($date){$q=DB::table('booking_itinerary_segments as event')->join('booking_services as bs','bs.id','=','event.booking_service_id')->select('event.*','bs.booking_id as booking_id')->whereNotNull('event.'.$date);if(($filters['from']??'')!=='')$q->whereDate('event.'.$date,'>=',$filters['from']);if(($filters['to']??'')!=='')$q->whereDate('event.'.$date,'<=',$filters['to']);if($from&&($filters['origin']??'')!=='')$q->where('event.'.$from,'like','%'.$filters['origin'].'%');if($to&&($filters['destination']??'')!=='')$q->where('event.'.$to,'like','%'.$filters['destination'].'%');if($flight&&($filters['flight']??'')!=='')$q->where('event.'.$flight,'like','%'.$filters['flight'].'%');if(Schema::hasTable('bookings'))foreach(['status'=>'status','branch'=>'branch_id','customer'=>'customer_id'] as $f=>$c)if(($filters[$f]??'')!==''&&Schema::hasColumn('bookings',$c))$q->whereExists(fn($x)=>$x->select(DB::raw(1))->from('bookings as b')->whereColumn('b.id','bs.booking_id')->where("b.$c",$filters[$f]));$events=$q->get();}
        }
        // Group-package flights remain a supported legacy movement source.
        if(Schema::hasTable($table)){$cols=Schema::getColumnListing($table);$type=$hotel?null:collect(['segment_type','type'])->first(fn($c)=>in_array($c,$cols,true));$date=$key==='arrival'?collect(['arrival_date','arrival_at','arrival_datetime'])->first(fn($c)=>in_array($c,$cols,true)):collect(['departure_date','departure_at','departure_datetime'])->first(fn($c)=>in_array($c,$cols,true));if($date){$q=DB::table($table.' as event')->select('event.*')->whereNotNull('event.'.$date);if($type)$q->whereIn('event.'.$type,['arrival','inbound','departure','outbound','outbound','return','connection']);if(($filters['from']??'')!=='')$q->whereDate('event.'.$date,'>=',$filters['from']);if(($filters['to']??'')!=='')$q->whereDate('event.'.$date,'<=',$filters['to']);if(Schema::hasTable('bookings')&&Schema::hasColumn($table,'booking_id'))$this->applyBookingRelationFilters($q,$filters,$table,'event');$events=$events->concat($q->get());}}
        return $events->unique(fn($e)=>implode('|',[strtolower(trim((string)($e->booking_id??''))),strtolower(trim((string)($e->flight_number??$e->flight_no??''))),strtolower(trim((string)($e->from??$e->from_code??$e->origin??''))),strtolower(trim((string)($e->to??$e->to_code??$e->destination??''))),strtolower(trim((string)($e->departure_at??$e->departure_date??''))),strtolower(trim((string)($e->arrival_at??$e->arrival_date??'')))]))->values();
    }
    // Legacy contract marker retained for compatibility: movementEventQuery,
    // movementPage and event.* remain event-grain authorities; streamRows now
