    private function movementEventRow(object $event,string $key): array { $id=(int)($event->booking_id??0);$booking=$this->bookingRecord($id);$context=Schema::hasTable('booking_group_package_unified')?DB::table('booking_group_package_unified')->where('booking_id',$id)->first():null;$b=$context?:$booking;$r=$this->blank($key);$p=$this->paxCounts($this->passengers->rows($id));$reference=$booking?$this->first($booking,['booking_reference','booking_ref','booking_no','booking_number']):'—';$r['booking_no']=$reference!=='—'?$reference:(string)$id;$customerIdentity=$this->customerResolver->resolve($id);$customerName=trim((string)($customerIdentity['name']??''));$r['customer']=$customerName!==''?$customerName:($booking?$this->first($booking,['customer_name','customer','party_name']):$this->first($b,['customer_name','customer','party_name']));$r['total_pax']=array_sum($p);$r['adult']=$p['adult'];$r['child']=$p['child'];$r['infant']=$p['infant'];$r['flight']=$event->flight_number??$event->flight_no??'—';$r['sector']=trim((string)($event->from_code??$event->from??$event->origin??'')).'-'.trim((string)($event->to_code??$event->to??$event->destination??''));$r['departure']=$event->departure_date??$event->departure_at??$event->departure_datetime??'—';$r['arrival']=$event->arrival_date??$event->arrival_at??$event->arrival_datetime??'—';$r['departure_date']=$this->movementDisplayDate($event,'departure');$r['arrival_date']=$this->movementDisplayDate($event,'arrival');$r['departure_time']=$this->movementTime($event,'departure');$r['arrival_time']=$this->movementTime($event,'arrival');$r['hotel']='—';$r['check_in']='—';$r['check_out']='—';$r['nights']='—';$r['package']=$this->first($b,['package_name','package_code','package_id','package']);$r['flight_sector']=$r['sector'];$r['makkah_hotel']=$this->movementHotels($id);$r['madinah_hotel']='—';$r['transport']=$this->movementTransport($id);$r['saudi_company']=$this->first($b,['saudi_company_name','saudi_company','saudi_company_id']);$r['p