    private function bookingBaseQuery(array $filters): \Illuminate\Database\Query\Builder { $q=DB::table('bookings');$cols=Schema::getColumnListing('bookings');$basis=$filters['date_type']??'booking';$date=$basis==='travel'?collect(['travel_date','departure_date','start_date'])->first(fn($c)=>in_array($c,$cols,true)):collect(['booking_date','date','created_at'])->first(fn($c)=>in_array($c,$cols,true));if($date){if(($filters['from']??'')!=='')$q->whereDate($date,'>=',$filters['from']);if(($filters['to']??'')!=='')$q->whereDate($date,'<=',$filters['to']);}$this->applyBookingRelationFilters($q,$filters,'bookings');if(($filters['product']??'')!=='')$this->applyProductExistence($q,$filters['product']);return$q; }
private function groupUmrahFieldAuthority(string $field, array $groupColumns): array { $aliases=['status'=>['status','workflow_status','booking_status'],'customer'=>['customer_name','customer','party_name','customer_id','party_id','client_id','customer_party_id'],'branch'=>['branch_name','branch','branch_id','office_id'],'agent'=>['agent_name','agent','agent_id'],'salesperson'=>['salesperson_name','salesperson','salesperson_id']][$field]??[];$groupColumn=collect($aliases)->first(fn($column)=>in_array($column,$groupColumns,true));if($groupColumn)return ['source'=>'group','column'=>$groupColumn,'aliases'=>$aliases];$bookingAliases=['status'=>['status','workflow_status','booking_status'],'customer'=>['customer_name','customer','party_name','customer_id','party_id','client_id','customer_party_id'],'branch'=>['branch_name','branch','branch_id','office_id'],'agent'=>['agent_name','agent','agent_id'],'salesperson'=>['salesperson_name','salesperson','salesperson_id']][$field]??[];return ['source'=>'booking','column'=>null,'aliases'=>$bookingAliases]; }
