    private function applyAirFiltersAdaptive(\Illuminate\Database\Query\Builder $q,array $filters): void {if(!Schema::hasTable('booking_itinerary_segments'))return;$segCols=Schema::getColumnListing('booking_itinerary_segments');$ticketCols=Schema::hasTable('air_ticket_details')?Schema::getColumnListing('air_ticket_details'):[];$pick=fn(array $cols,array $names)=>collect($names)->first(fn($name)=>in_array($name,$cols,true));$airline=$pick($segCols,['airline_code','airline_name','airline_id','airline']);$origin=$pick($segCols,['from','from_code','origin','origin_code']);$destination=$pick($segCols,['to','to_code','destination','destination_code']);$departure=$pick($segCols,['departure_at','departure_datetime','departure_date']);$ticketNo=$pick($ticketCols,['ticket_number','ticket_no']);$ticketStatus=$pick($ticketCols,['ticket_status','status']);$issue=$pick($ticketCols,['issue_date','issued_at']);$segment=fn($x)=>$x->select(DB::raw(1))->from('booking_itinerary_segments as bis')->whereColumn('bis.booking_service_id','booking_services.id');$ticket=fn($x)=>$x->select(DB::raw(1))->from('air_ticket_details as atd')->whereColumn('atd.booking_service_id','booking_services.id');if(($filters['airline']??'')!==''&&$airline)$q->whereExists(fn($x)=>$segment($x)->whereRaw("LOWER(TRIM(bis.$airline)) like ?",['%'.strtolower(trim((string)$filters['airline'])).'%']));if(($filters['origin']??'')!==''&&$origin)$q->whereExists(fn($x)=>$segment($x)->where("bis.$origin",'like','%'.$filters['origin'].'%'));if(($filters['destination']??'')!==''&&$destination)$q->whereExists(fn($x)=>$segment($x)->where("bis.$destination",'like','%'.$filters['destination'].'%'));if(($filters['sector']??'')!==''&&$origin&&$destination)$q->whereExists(fn($x)=>$segment($x)->whereRaw("UPPER(CONCAT(TRIM(bis.$origin), ' → ', TRIM(bis.$destination))) like ?",['%'.strtoupper(trim((string)$filters['sector'])).'%']));$basis=$filters['date_type']??'departure';if(($filters['from']??'')!==''||($filters['to']??'')!==''){if($basis==='issue'&&$issue)$q->whereExists(fn($x)=>$ticket($x)->when($filters['from']??null,fn($w,$v)=>$w->whereDate("atd.$issue",'>=',$v))->when($filters['to']??null,fn($w,$v)=>$w->whereDate("atd.$issue",'<=',$v)));elseif($departure)$q->whereExists(fn($x)=>$segment($x)->when($filters['from']??null,fn($w,$v)=>$w->whereDate("bis.$departure",'>=',$v))->when($filters['to']??null,fn($w,$v)=>$w->whereDate("bis.$departure",'<=',$v)));}if(($filters['ticket_status']??'')!==''&&$ticketStatus)$q->whereExists(fn($x)=>$ticket($x)->where("atd.$ticketStatus",$filters['ticket_status']));if(($filters['ticket_no']??'')!==''&&$ticketNo)$q->whereExists(fn($x)=>$ticket($x)->where("atd.$ticketNo",'like','%'.$filters['ticket_no'].'%'));if(($filters['issue_date']??'')!==''&&$issue)$q->whereExists(fn($x)=>$ticket($x)->whereDate("atd.$issue",$filters['issue_date']));if(Schema::hasTable('bookings'))foreach(['branch'=>'branch_id','customer'=>'customer_id','agent'=>'agent_id','salesperson'=>'salesperson_id'] as $filter=>$column)if(($filters[$filter]??'')!==''&&Schema::hasColumn('bookings',$column))$q->whereExists(fn($x)=>$x->select(DB::raw(1))->from('bookings as b')->whereColumn('b.id','booking_services.booking_id')->where("b.$column",$filters[$filter]));if(($filters['pnr']??'')!==''&&Schema::hasColumn('booking_services','pnr'))$q->where('pnr','like','%'.$filters['pnr'].'%');$serviceCols=Schema::getColumnListing('booking_services');$vendor=collect(['vendor_name','supplier_name','vendor_id','supplier_id'])->first(fn($c)=>in_array($c,$serviceCols,true));if(($filters['vendor']??'')!==''&&$vendor)$q->whereRaw("LOWER(TRIM(booking_services.$vendor)) like ?",['%'.strtolower(trim((string)$filters['vendor'])).'%']);}
