    private function movementArrivalTime(object $event): string { $direct=trim((string)($event->arrival_time??''));if($direct!==''){if(preg_match('/^\d{1,2}:\d{2}/',$direct,$m))return str_pad($m[0],5,'0',STR_PAD_LEFT);return$direct;}foreach(['arrival_at','arrival_datetime'] as $field){$value=trim((string)($event->{$field}??''));if($value==='')continue;if(preg_match('/(?:^|[T\s])(\d{1,2}:\d{2})(?::\d{2})?/', $value,$m))return str_pad($m[1],5,'0',STR_PAD_LEFT);}return'—'; }
