    private function movementTransport(int $id): string { if(!$id||!Schema::hasTable('booking_group_package_transports'))return'—';$cols=Schema::getColumnListing('booking_group_package_transports');if(!in_array('booking_id',$cols,true))return'—';$route=collect(['route_name','route'])->first(fn($c)=>in_array($c,$cols,true));$from=collect(['from_location','from','origin'])->first(fn($c)=>in_array($c,$cols,true));$to=collect(['to_location','to','destination'])->first(fn($c)=>in_array($c,$cols,true));$select=$route?$route:($from&&$to?DB::raw("CONCAT(COALESCE(`$from`,''),' -> ',COALESCE(`$to`,''))"):null);if(!$select)return'—';$values=DB::table('booking_group_package_transports')->where('booking_id',$id)->pluck($select)->map(fn($v)=>trim((string)$v))->filter(fn($v)=>$v!=='->'&&$v!=='')->unique()->sort()->values();return$values->isEmpty()?'—':$values->implode(', '); }
